{
  "source_url": "https://ethereum.github.io/consensus-specs/specs/fulu/polynomial-commitments-sampling/",
  "title": "Fulu -- Polynomial Commitments Sampling",
  "category": "consensus-spec",
  "type": "Specification",
  "status": "Active",
  "layer": "consensus/cryptography",
  "sub_graphs": [
    {
      "id": "SG-001",
      "name": "Data Types",
      "description": "Core data types used throughout the polynomial commitments sampling specification. These types define the fundamental units of blob data, cell indexing, and commitment indexing for the DAS (Data Availability Sampling) protocol extension.",
      "invariants": [
        {
          "id": "INV-001",
          "text": "CellIndex must satisfy x < CELLS_PER_EXT_BLOB."
        },
        {
          "id": "INV-002",
          "text": "Cell is a fixed-size byte vector of length BYTES_PER_FIELD_ELEMENT * FIELD_ELEMENTS_PER_CELL."
        }
      ],
      "functions": [],
      "state_variables": [
        {
          "id": "SV-001",
          "name": "Cell",
          "type": "ByteVector[BYTES_PER_FIELD_ELEMENT * FIELD_ELEMENTS_PER_CELL]",
          "description": "The unit of blob data that can come with its own KZG proof."
        },
        {
          "id": "SV-002",
          "name": "CellIndex",
          "type": "uint64",
          "description": "Index type for cells within an extended blob, validated as x < CELLS_PER_EXT_BLOB."
        },
        {
          "id": "SV-003",
          "name": "CommitmentIndex",
          "type": "uint64",
          "description": "The type which represents the index of an element in the list of commitments."
        }
      ],
      "data_structures": [
        {
          "id": "DS-001",
          "name": "Cell",
          "ssz_equivalent": "ByteVector[BYTES_PER_FIELD_ELEMENT * FIELD_ELEMENTS_PER_CELL]"
        },
        {
          "id": "DS-002",
          "name": "CellIndex",
          "ssz_equivalent": "uint64"
        },
        {
          "id": "DS-003",
          "name": "CommitmentIndex",
          "ssz_equivalent": "uint64"
        }
      ]
    },
    {
      "id": "SG-002",
      "name": "Cryptographic Types",
      "description": "Cryptographic type aliases used for polynomial arithmetic and cell evaluation in the KZG commitment scheme. These types define polynomial representations in coefficient form, evaluation coset domains, and cell evaluation results.",
      "invariants": [
        {
          "id": "INV-003",
          "text": "PolynomialCoeff length must not exceed FIELD_ELEMENTS_PER_EXT_BLOB."
        },
        {
          "id": "INV-004",
          "text": "Coset is a fixed-size vector of exactly FIELD_ELEMENTS_PER_CELL elements."
        },
        {
          "id": "INV-005",
          "text": "CosetEvals is a fixed-size vector of exactly FIELD_ELEMENTS_PER_CELL elements."
        }
      ],
      "functions": [],
      "state_variables": [],
      "data_structures": [
        {
          "id": "DS-004",
          "name": "PolynomialCoeff",
          "ssz_equivalent": "List[BLSFieldElement, FIELD_ELEMENTS_PER_EXT_BLOB]",
          "description": "A polynomial in coefficient form."
        },
        {
          "id": "DS-005",
          "name": "Coset",
          "ssz_equivalent": "Vector[BLSFieldElement, FIELD_ELEMENTS_PER_CELL]",
          "description": "The evaluation domain of a cell."
        },
        {
          "id": "DS-006",
          "name": "CosetEvals",
          "ssz_equivalent": "Vector[BLSFieldElement, FIELD_ELEMENTS_PER_CELL]",
          "description": "A cell's evaluations over its coset."
        }
      ]
    },
    {
      "id": "SG-003",
      "name": "Preset Constants (Blob)",
      "description": "Preset constants that define the dimensions and parameters for blob encoding, Reed-Solomon extension, and cell structure. These constants determine the size of the extended blob, the granularity of cells, and domain separator tags for batch verification.",
      "invariants": [
        {
          "id": "INV-006",
          "text": "FIELD_ELEMENTS_PER_EXT_BLOB = 2 * FIELD_ELEMENTS_PER_BLOB (Reed-Solomon doubles the field elements)."
        },
        {
          "id": "INV-007",
          "text": "BYTES_PER_CELL = FIELD_ELEMENTS_PER_CELL * BYTES_PER_FIELD_ELEMENT."
        },
        {
          "id": "INV-008",
          "text": "CELLS_PER_EXT_BLOB = FIELD_ELEMENTS_PER_EXT_BLOB / FIELD_ELEMENTS_PER_CELL."
        }
      ],
      "functions": [],
      "state_variables": [
        {
          "id": "SV-004",
          "name": "FIELD_ELEMENTS_PER_EXT_BLOB",
          "type": "uint64",
          "value": "2 * FIELD_ELEMENTS_PER_BLOB",
          "description": "Number of field elements in a Reed-Solomon extended blob."
        },
        {
          "id": "SV-005",
          "name": "FIELD_ELEMENTS_PER_CELL",
          "type": "uint64",
          "value": "64",
          "description": "Number of field elements in a cell."
        },
        {
          "id": "SV-006",
          "name": "BYTES_PER_CELL",
          "type": "uint64",
          "value": "FIELD_ELEMENTS_PER_CELL * BYTES_PER_FIELD_ELEMENT",
          "description": "The number of bytes in a cell."
        },
        {
          "id": "SV-007",
          "name": "CELLS_PER_EXT_BLOB",
          "type": "uint64",
          "value": "FIELD_ELEMENTS_PER_EXT_BLOB // FIELD_ELEMENTS_PER_CELL",
          "description": "The number of cells in an extended blob."
        },
        {
          "id": "SV-008",
          "name": "RANDOM_CHALLENGE_KZG_CELL_BATCH_DOMAIN",
          "type": "bytes",
          "value": "b'RCKZGCBATCH__V1_'",
          "description": "Domain separator tag for batch KZG cell proof verification challenges."
        }
      ],
      "data_structures": []
    },
    {
      "id": "SG-004",
      "name": "BLS12-381 Helpers",
      "description": "Helper functions for converting between the Cell byte representation and the CosetEvals field element representation. These form the serialization/deserialization boundary between untrusted byte data and trusted algebraic field elements on the BLS12-381 curve.",
      "invariants": [
        {
          "id": "INV-009",
          "text": "cell_to_coset_evals(coset_evals_to_cell(evals)) == evals for any valid CosetEvals."
        },
        {
          "id": "INV-010",
          "text": "Each field element in a Cell must be a valid BLS field element (less than BLS_MODULUS)."
        }
      ],
      "functions": [
        {
          "id": "FN-001",
          "name": "cell_to_coset_evals",
          "signature": "def cell_to_coset_evals(cell: Cell) -> CosetEvals",
          "description": "Convert an untrusted Cell (byte representation) into a trusted CosetEvals (field element representation). Iterates over FIELD_ELEMENTS_PER_CELL chunks of BYTES_PER_FIELD_ELEMENT bytes and deserializes each via bytes_to_bls_field.",
          "parameters": [
            {"name": "cell", "type": "Cell", "description": "The untrusted cell byte vector to convert."}
          ],
          "returns": "CosetEvals",
          "preconditions": [
            "cell contains FIELD_ELEMENTS_PER_CELL * BYTES_PER_FIELD_ELEMENT bytes",
            "Each BYTES_PER_FIELD_ELEMENT-byte chunk is a valid serialized BLS field element"
          ],
          "postconditions": [
            "Returned CosetEvals has exactly FIELD_ELEMENTS_PER_CELL elements",
            "Each element is a validated BLSFieldElement"
          ]
        },
        {
          "id": "FN-002",
          "name": "coset_evals_to_cell",
          "signature": "def coset_evals_to_cell(coset_evals: CosetEvals) -> Cell",
          "description": "Convert a trusted CosetEvals (field element representation) into an untrusted Cell (byte representation). Serializes each field element via bls_field_to_bytes.",
          "parameters": [
            {"name": "coset_evals", "type": "CosetEvals", "description": "The trusted coset evaluations to serialize."}
          ],
          "returns": "Cell",
          "preconditions": [
            "coset_evals has exactly FIELD_ELEMENTS_PER_CELL elements"
          ],
          "postconditions": [
            "Returned Cell has exactly BYTES_PER_CELL bytes"
          ]
        }
      ],
      "state_variables": [],
      "data_structures": []
    },
    {
      "id": "SG-005",
      "name": "Fast Fourier Transform (FFT) Operations",
      "description": "Implementations of the Fast Fourier Transform over BLS12-381 field elements. Provides forward and inverse FFT, as well as coset FFT for evaluation/interpolation over cosets of roots of unity. Also includes the Fiat-Shamir challenge computation for batch verification.",
      "invariants": [
        {
          "id": "INV-011",
          "text": "fft_field(fft_field(vals, roots, inv=True), roots) == vals (FFT roundtrip)."
        },
        {
          "id": "INV-012",
          "text": "Input length must be a power of 2 for _fft_field."
        },
        {
          "id": "INV-013",
          "text": "coset_fft_field(coset_fft_field(vals, roots), roots, inv=True) == vals (coset FFT roundtrip)."
        }
      ],
      "functions": [
        {
          "id": "FN-003",
          "name": "_fft_field",
          "signature": "def _fft_field(vals: Sequence[BLSFieldElement], roots_of_unity: Sequence[BLSFieldElement]) -> Sequence[BLSFieldElement]",
          "description": "Internal recursive Cooley-Tukey FFT implementation over BLS field elements. Splits input into even/odd indices, recurses, then combines using butterfly operations with roots of unity.",
          "parameters": [
            {"name": "vals", "type": "Sequence[BLSFieldElement]", "description": "Input values to transform."},
            {"name": "roots_of_unity", "type": "Sequence[BLSFieldElement]", "description": "Roots of unity for the FFT domain."}
          ],
          "returns": "Sequence[BLSFieldElement]",
          "preconditions": [
            "len(vals) is a power of 2",
            "len(roots_of_unity) == len(vals)"
          ],
          "postconditions": [
            "Output has same length as input"
          ]
        },
        {
          "id": "FN-004",
          "name": "fft_field",
          "signature": "def fft_field(vals: Sequence[BLSFieldElement], roots_of_unity: Sequence[BLSFieldElement], inv: bool = False) -> Sequence[BLSFieldElement]",
          "description": "Wrapper for forward and inverse FFT over BLS field elements. For inverse FFT, reverses the roots of unity (except the first element) and scales the result by 1/len(vals).",
          "parameters": [
            {"name": "vals", "type": "Sequence[BLSFieldElement]", "description": "Input values."},
            {"name": "roots_of_unity", "type": "Sequence[BLSFieldElement]", "description": "Roots of unity."},
            {"name": "inv", "type": "bool", "description": "If True, compute inverse FFT."}
          ],
          "returns": "Sequence[BLSFieldElement]",
          "preconditions": [
            "len(vals) is a power of 2"
          ],
          "postconditions": [
            "If inv=False, returns DFT of vals",
            "If inv=True, returns inverse DFT of vals"
          ]
        },
        {
          "id": "FN-005",
          "name": "coset_fft_field",
          "signature": "def coset_fft_field(vals: Sequence[BLSFieldElement], roots_of_unity: Sequence[BLSFieldElement], inv: bool = False) -> Sequence[BLSFieldElement]",
          "description": "Computes an FFT/IFFT over a coset of the roots of unity. Uses PRIMITIVE_ROOT_OF_UNITY as the coset generator (shift factor). Useful for dividing by polynomials that vanish on elements of the standard FFT domain.",
          "parameters": [
            {"name": "vals", "type": "Sequence[BLSFieldElement]", "description": "Input values."},
            {"name": "roots_of_unity", "type": "Sequence[BLSFieldElement]", "description": "Roots of unity for the FFT domain."},
            {"name": "inv", "type": "bool", "description": "If True, compute inverse coset FFT."}
          ],
          "returns": "Sequence[BLSFieldElement]",
          "preconditions": [
            "len(vals) is a power of 2"
          ],
          "postconditions": [
            "Result represents evaluations over the coset h*G where h = PRIMITIVE_ROOT_OF_UNITY"
          ]
        },
        {
          "id": "FN-006",
          "name": "compute_verify_cell_kzg_proof_batch_challenge",
          "signature": "def compute_verify_cell_kzg_proof_batch_challenge(commitments: Sequence[KZGCommitment], commitment_indices: Sequence[CommitmentIndex], cell_indices: Sequence[CellIndex], cosets_evals: Sequence[CosetEvals], proofs: Sequence[KZGProof]) -> BLSFieldElement",
          "description": "Computes a random challenge r used in the universal verification equation via the Fiat-Shamir heuristic. Hashes together the domain separator RANDOM_CHALLENGE_KZG_CELL_BATCH_DOMAIN, preset parameters, commitments, cell indices, evaluations, and proofs to produce a deterministic pseudo-random field element.",
          "parameters": [
            {"name": "commitments", "type": "Sequence[KZGCommitment]", "description": "List of KZG commitments."},
            {"name": "commitment_indices", "type": "Sequence[CommitmentIndex]", "description": "Indices mapping cells to commitments."},
            {"name": "cell_indices", "type": "Sequence[CellIndex]", "description": "Cell indices being verified."},
            {"name": "cosets_evals", "type": "Sequence[CosetEvals]", "description": "Evaluations for each cell."},
            {"name": "proofs", "type": "Sequence[KZGProof]", "description": "KZG proofs for each cell."}
          ],
          "returns": "BLSFieldElement",
          "preconditions": [
            "All input sequences have consistent lengths",
            "commitment_indices[k] < len(commitments) for all k"
          ],
          "postconditions": [
            "Returned field element is deterministically derived from all inputs",
            "Challenge is binding to all prover-provided data"
          ]
        }
      ],
      "state_variables": [],
      "data_structures": []
    },
    {
      "id": "SG-006",
      "name": "Polynomial Coefficient Form Arithmetic",
      "description": "A comprehensive library of polynomial arithmetic operations in coefficient form over BLS12-381 field elements. Includes conversion from evaluation form, addition, multiplication, division, Lagrange interpolation, vanishing polynomial construction, and Horner evaluation.",
      "invariants": [
        {
          "id": "INV-014",
          "text": "multiply_polynomialcoeff requires len(a) + len(b) <= FIELD_ELEMENTS_PER_EXT_BLOB."
        },
        {
          "id": "INV-015",
          "text": "For interpolate_polynomialcoeff, len(xs) must equal len(ys)."
        },
        {
          "id": "INV-016",
          "text": "divide_polynomialcoeff performs exact polynomial long division (no remainder check)."
        },
        {
          "id": "INV-017",
          "text": "vanishing_polynomialcoeff(xs) evaluates to zero at every x in xs."
        },
        {
          "id": "INV-018",
          "text": "evaluate_polynomialcoeff(interpolate_polynomialcoeff(xs, ys), xs[i]) == ys[i] for all i."
        }
      ],
      "functions": [
        {
          "id": "FN-007",
          "name": "polynomial_eval_to_coeff",
          "signature": "def polynomial_eval_to_coeff(polynomial: Polynomial) -> PolynomialCoeff",
          "description": "Interpolates a polynomial given in evaluation form to coefficient form using inverse FFT with bit-reversal permutation over FIELD_ELEMENTS_PER_BLOB roots of unity.",
          "parameters": [
            {"name": "polynomial", "type": "Polynomial", "description": "Polynomial in evaluation form."}
          ],
          "returns": "PolynomialCoeff",
          "preconditions": [
            "polynomial has FIELD_ELEMENTS_PER_BLOB evaluations"
          ],
          "postconditions": [
            "Returned polynomial in coefficient form has degree at most FIELD_ELEMENTS_PER_BLOB - 1"
          ]
        },
        {
          "id": "FN-008",
          "name": "add_polynomialcoeff",
          "signature": "def add_polynomialcoeff(a: PolynomialCoeff, b: PolynomialCoeff) -> PolynomialCoeff",
          "description": "Sums two coefficient-form polynomials by adding corresponding coefficients, padding the shorter polynomial with zeros.",
          "parameters": [
            {"name": "a", "type": "PolynomialCoeff", "description": "First polynomial."},
            {"name": "b", "type": "PolynomialCoeff", "description": "Second polynomial."}
          ],
          "returns": "PolynomialCoeff",
          "postconditions": [
            "Result length equals max(len(a), len(b))"
          ]
        },
        {
          "id": "FN-009",
          "name": "multiply_polynomialcoeff",
          "signature": "def multiply_polynomialcoeff(a: PolynomialCoeff, b: PolynomialCoeff) -> PolynomialCoeff",
          "description": "Multiplies two coefficient-form polynomials using the schoolbook (naive) O(n^2) algorithm. Asserts the combined degree does not exceed FIELD_ELEMENTS_PER_EXT_BLOB.",
          "parameters": [
            {"name": "a", "type": "PolynomialCoeff", "description": "First polynomial."},
            {"name": "b", "type": "PolynomialCoeff", "description": "Second polynomial."}
          ],
          "returns": "PolynomialCoeff",
          "preconditions": [
            "len(a) + len(b) <= FIELD_ELEMENTS_PER_EXT_BLOB"
          ],
          "postconditions": [
            "Result degree is at most deg(a) + deg(b)"
          ]
        },
        {
          "id": "FN-010",
          "name": "divide_polynomialcoeff",
          "signature": "def divide_polynomialcoeff(a: PolynomialCoeff, b: PolynomialCoeff) -> PolynomialCoeff",
          "description": "Performs long polynomial division of a by b in coefficient form. Returns the quotient polynomial. Assumes b divides a exactly (remainder is discarded).",
          "parameters": [
            {"name": "a", "type": "PolynomialCoeff", "description": "Dividend polynomial."},
            {"name": "b", "type": "PolynomialCoeff", "description": "Divisor polynomial."}
          ],
          "returns": "PolynomialCoeff",
          "preconditions": [
            "b is non-zero",
            "deg(a) >= deg(b)"
          ],
          "postconditions": [
            "Result has degree deg(a) - deg(b)"
          ]
        },
        {
          "id": "FN-011",
          "name": "interpolate_polynomialcoeff",
          "signature": "def interpolate_polynomialcoeff(xs: Sequence[BLSFieldElement], ys: Sequence[BLSFieldElement]) -> PolynomialCoeff",
          "description": "Lagrange interpolation: finds the lowest degree polynomial passing through all (xs[i], ys[i]) points. Outputs in coefficient form. Uses the standard O(n^2) Lagrange basis construction.",
          "parameters": [
            {"name": "xs", "type": "Sequence[BLSFieldElement]", "description": "X coordinates (evaluation points)."},
            {"name": "ys", "type": "Sequence[BLSFieldElement]", "description": "Y coordinates (evaluation values)."}
          ],
          "returns": "PolynomialCoeff",
          "preconditions": [
            "len(xs) == len(ys)",
            "All xs[i] are distinct"
          ],
          "postconditions": [
            "Result polynomial has degree at most len(xs) - 1",
            "evaluate_polynomialcoeff(result, xs[i]) == ys[i] for all i"
          ]
        },
        {
          "id": "FN-012",
          "name": "vanishing_polynomialcoeff",
          "signature": "def vanishing_polynomialcoeff(xs: Sequence[BLSFieldElement]) -> PolynomialCoeff",
          "description": "Computes the vanishing polynomial on xs in coefficient form: product of (X - xs[i]) for all i. The resulting polynomial evaluates to zero at every point in xs.",
          "parameters": [
            {"name": "xs", "type": "Sequence[BLSFieldElement]", "description": "Points at which the polynomial vanishes."}
          ],
          "returns": "PolynomialCoeff",
          "postconditions": [
            "Result has degree len(xs)",
            "Result is monic (leading coefficient is 1)",
            "evaluate_polynomialcoeff(result, xs[i]) == 0 for all i"
          ]
        },
        {
          "id": "FN-013",
          "name": "evaluate_polynomialcoeff",
          "signature": "def evaluate_polynomialcoeff(polynomial_coeff: PolynomialCoeff, z: BLSFieldElement) -> BLSFieldElement",
          "description": "Evaluates a coefficient-form polynomial at point z using Horner's method for O(n) efficiency.",
          "parameters": [
            {"name": "polynomial_coeff", "type": "PolynomialCoeff", "description": "Polynomial in coefficient form."},
            {"name": "z", "type": "BLSFieldElement", "description": "Point at which to evaluate."}
          ],
          "returns": "BLSFieldElement"
        }
      ],
      "state_variables": [],
      "data_structures": []
    },
    {
      "id": "SG-007",
      "name": "KZG Multi-Evaluation Proofs",
      "description": "Functions for computing and verifying KZG multi-evaluation proofs. The computation constructs a quotient polynomial Q(X) = f(X) / Z(X) where Z(X) vanishes on the evaluation points. The verification implements a universal batched pairing check using random linear combinations via the Fiat-Shamir heuristic.",
      "invariants": [
        {
          "id": "INV-019",
          "text": "For compute_kzg_proof_multi_impl: Q(X) = f(X) / Z(X) holds exactly when f(X) evaluates correctly at all points in zs."
        },
        {
          "id": "INV-020",
          "text": "For verify_cell_kzg_proof_batch_impl: the verification equation is pairing(LL, LR) == pairing(RL, [1])."
        },
        {
          "id": "INV-021",
          "text": "The commitments list in verify_cell_kzg_proof_batch_impl must contain no duplicates."
        },
        {
          "id": "INV-022",
          "text": "All commitment_indices must be less than len(commitments)."
        }
      ],
      "functions": [
        {
          "id": "FN-014",
          "name": "compute_kzg_proof_multi_impl",
          "signature": "def compute_kzg_proof_multi_impl(polynomial_coeff: PolynomialCoeff, zs: Coset) -> Tuple[KZGProof, CosetEvals]",
          "description": "Computes a KZG multi-evaluation proof for a set of k points. Constructs the quotient polynomial Q(X) = f(X) / Z(X), where Z(X) is the vanishing polynomial over the evaluation points zs. The proof is the commitment to Q(X) via g1_lincomb with the monomial SRS. Also returns the evaluations ys = f(zs).",
          "parameters": [
            {"name": "polynomial_coeff", "type": "PolynomialCoeff", "description": "The polynomial to prove evaluations of, in coefficient form."},
            {"name": "zs", "type": "Coset", "description": "The set of evaluation points (a coset)."}
          ],
          "returns": "Tuple[KZGProof, CosetEvals]",
          "preconditions": [
            "polynomial_coeff is a valid polynomial in coefficient form",
            "zs has FIELD_ELEMENTS_PER_CELL elements"
          ],
          "postconditions": [
            "Returned proof is a valid G1 point",
            "Returned ys[i] == evaluate_polynomialcoeff(polynomial_coeff, zs[i]) for all i"
          ]
        },
        {
          "id": "FN-015",
          "name": "verify_cell_kzg_proof_batch_impl",
          "signature": "def verify_cell_kzg_proof_batch_impl(commitments: Sequence[KZGCommitment], commitment_indices: Sequence[CommitmentIndex], cell_indices: Sequence[CellIndex], cosets_evals: Sequence[CosetEvals], proofs: Sequence[KZGProof]) -> bool",
          "description": "Verifies that a set of cells belong to their corresponding commitments using a batched pairing check. Implements the universal verification equation: pairing(LL, LR) = pairing(RL, [1]) where LL = sum_k(r^k * proofs[k]), LR = [s^n], and RL = RLC - RLI + RLP. Uses Fiat-Shamir for random challenge r. This achieves efficient batch verification with only 2 pairing operations regardless of the number of cells.",
          "parameters": [
            {"name": "commitments", "type": "Sequence[KZGCommitment]", "description": "Deduplicated list of KZG commitments."},
            {"name": "commitment_indices", "type": "Sequence[CommitmentIndex]", "description": "Maps each cell to its commitment."},
            {"name": "cell_indices", "type": "Sequence[CellIndex]", "description": "Cell indices being verified."},
            {"name": "cosets_evals", "type": "Sequence[CosetEvals]", "description": "Cell evaluations."},
            {"name": "proofs", "type": "Sequence[KZGProof]", "description": "KZG proofs for each cell."}
          ],
          "returns": "bool",
          "preconditions": [
            "len(commitment_indices) == len(cell_indices) == len(cosets_evals) == len(proofs)",
            "commitments contains no duplicates",
            "commitment_indices[k] < len(commitments) for all k"
          ],
          "postconditions": [
            "Returns True if and only if all cells are valid evaluations of their committed polynomials over the specified coset domains"
          ],
          "state_transitions": [
            {
              "id": "ST-001",
              "description": "Step 1: Compute Fiat-Shamir challenge r and powers r^0..r^{num_cells-1}."
            },
            {
              "id": "ST-002",
              "description": "Step 2: Compute LL = sum_k(r^k * proofs[k]) via g1_lincomb."
            },
            {
              "id": "ST-003",
              "description": "Step 3: Compute LR = [s^n] from KZG_SETUP_G2_MONOMIAL."
            },
            {
              "id": "ST-004",
              "description": "Step 4.1: Compute RLC = sum_i(weights[i] * commitments[i]) where weights[i] = sum of r^k for all k associated with commitment i."
            },
            {
              "id": "ST-005",
              "description": "Step 4.2: Compute RLI = [sum_k(r^k * interpolation_poly_k(s))] using Lagrange interpolation for each cell."
            },
            {
              "id": "ST-006",
