    {
      "id": "SG-011",
      "name": "Cell and Polynomial Reconstruction",
      "description": "Functions for recovering missing cells and their KZG proofs given at least 50% of the cells from a blob. Uses Reed-Solomon erasure coding recovery via FFTs. The reconstruction algorithm operates by computing a vanishing polynomial over missing cells, multiplying with available evaluations, performing polynomial division over a coset to avoid division by zero, and recovering the original polynomial.",
      "invariants": [
