          "name": "recover_polynomialcoeff",
          "signature": "def recover_polynomialcoeff(cell_indices: Sequence[CellIndex], cosets_evals: Sequence[CosetEvals]) -> PolynomialCoeff",
          "description": "Recovers the original polynomial (in coefficient form) from partial cell evaluations using the Reed-Solomon erasure recovery algorithm. The algorithm: (1) constructs E(x) from available evaluations (zeros for missing cells), (2) computes vanishing polynomial Z(x) for missing cells, (3) multiplies E(x)*Z(x) in evaluation form (which equals P(x)*Z(x) over the FFT domain), (4) converts to coefficient form via inverse FFT, (5) divides P(x)*Z(x) by Z(x) over a coset domain (to avoid division by zero), (6) converts back to coefficient form.",
          "parameters": [
            {"name": "cell_indices", "type": "Sequence[CellIndex]", "description": "Indices of available cells."},
            {"name": "cosets_evals", "type": "Sequence[CosetEvals]", "description": "Evaluations for the available cells."}
          ],
          "returns": "PolynomialCoeff",
          "postconditions": [
            "Returned polynomial has at most FIELD_ELEMENTS_PER_BLOB coefficients",
            "When evaluated at the coset points, the polynomial reproduces the available cell evaluations"
          ],
          "state_transitions": [
            {
              "id": "ST-013",
              "description": "Step 1: Flatten available evaluations into extended_evaluation (zeros for missing cells), apply bit-reversal permutation."
            },
