    {
      "id": "SG-005",
      "name": "Validator Custody Requirement Computation",
      "description": "Defines the mechanism by which validator nodes compute their custody requirement. A node with validators computes its minimum custody groups based on the total effective balance of all attached validators, with a floor of VALIDATOR_CUSTODY_REQUIREMENT and a ceiling of NUMBER_OF_CUSTODY_GROUPS. The custody count scales linearly with total balance at a rate of one additional group per BALANCE_PER_ADDITIONAL_CUSTODY_GROUP (32 ETH).",
      "invariants": [
        {
          "id": "INV-008",
          "text": "VALIDATOR_CUSTODY_REQUIREMENT <= get_validators_custody_requirement(state, indices) <= NUMBER_OF_CUSTODY_GROUPS: the result is always bounded between the minimum validator custody and the total number of groups."
        },
        {
          "id": "INV-009",
          "text": "The custody requirement is deterministic: given the same state and validator_indices, the result is always identical."
        },
        {
          "id": "INV-010",
          "text": "Custody groups are computed from the total effective balance of all attached validators, not individual validator balances."
        },
        {
          "id": "INV-011",
          "text": "A node with at least one validator must custody at minimum VALIDATOR_CUSTODY_REQUIREMENT (8) groups, regardless of balance."
        }
      ],
      "pre_conditions": [
        {
          "id": "PRE-002",
          "text": "state must be the latest finalized BeaconState."
        },
        {
          "id": "PRE-003",
          "text": "validator_indices must be the list of indices corresponding to validators attached to the node."
        },
        {
          "id": "PRE-004",
          "text": "Each index in validator_indices must be a valid ValidatorIndex within state.validators."
        }
      ],
      "post_conditions": [
        {
          "id": "POST-002",
          "text": "Returns a uint64 representing the minimum number of custody groups the node must custody."
        }
      ],
      "functions": [
        {
          "id": "FN-002",
          "signature": "get_validators_custody_requirement(state: BeaconState, validator_indices: Sequence[ValidatorIndex]) -> uint64",
          "description": "Computes the minimum custody group count for a validator node. Sums effective balances of all attached validators, divides by BALANCE_PER_ADDITIONAL_CUSTODY_GROUP, and clamps between VALIDATOR_CUSTODY_REQUIREMENT and NUMBER_OF_CUSTODY_GROUPS.",
          "classification": "public"
        }
      ],
      "data_structures": [],
      "state_variables": []
    },
    {
      "id": "SG-006",
      "name": "Validator Custody Behavioral Rules",
      "description": "Specifies the behavioral rules for honest validator nodes regarding custody advertisement, dynamic adjustment, and persistence. Covers how nodes should respond to changes in custody requirements, including increasing and decreasing scenarios, backfill behavior, and ENR/Metadata advertising.",
      "invariants": [
        {
          "id": "INV-012",
          "text": "The higher custody is advertised in the node's Metadata by setting custody_group_count and in the node's ENR by setting custody_group_count."
        },
        {
          "id": "INV-013",
          "text": "A node with validators MAY custody, advertise, and serve more than the computed minimum."
        },
        {
          "id": "INV-014",
          "text": "A node MUST backfill columns when syncing, consistent with regular custody requirements."
        }
      ],
      "pre_conditions": [],
      "post_conditions": [],
      "functions": [],
      "data_structures": [],
      "state_variables": [],
      "behavioral_rules": [
        {
          "id": "BR-001",
          "level": "SHOULD",
          "text": "A node SHOULD dynamically adjust its custody groups (without user input) following any changes to the total effective balances of attached validators."
        },
        {
          "id": "BR-002",
          "level": "SHOULD",
          "text": "If the node's custody requirements are increased, it SHOULD immediately advertise the updated custody_group_count."
        },
        {
          "id": "BR-003",
          "level": "MAY",
          "text": "If custody requirements are increased, the node MAY backfill custody groups as a result of this change."
        },
        {
          "id": "BR-004",
          "level": "SHOULD_NOT",
          "text": "If a node's custody requirements decrease, it SHOULD NOT update the custody_group_count to reflect this reduction."
        },
        {
          "id": "BR-005",
          "level": "SHOULD",
          "text": "If custody requirements decrease, the node SHOULD continue to custody and advertise the previous (highest) custody_group_count."
        },
        {
          "id": "BR-006",
          "level": "SHOULD",
          "text": "If custody requirements decrease, the node SHOULD continue to respond to any DataColumnSidecar request corresponding to the previous (highest) custody_group_count."
        },
        {
          "id": "BR-007",
          "level": "SHOULD",
          "text": "The previous (highest) custody_group_count SHOULD persist across node restarts."
        },
        {
          "id": "BR-008",
          "level": "SHOULD",
          "text": "Nodes SHOULD be capable of handling multiple changes to custody requirements within the same retention period (e.g., an increase in one epoch followed by a decrease in the next)."
        },
        {
          "id": "BR-009",
          "level": "SHOULD",
          "text": "When a value for custody_group_count is set, the earliest_available_slot field in the status RPC message SHOULD reflect the slot at which the custody_group_count was updated."
        },
        {
          "id": "BR-010",
          "level": "MAY",
          "text": "If the node decides to backfill due to custody_group_count change, the earliest_available_slot field in the status RPC message MAY be updated with progressively lower values as the backfill process advances."
        }
      ]
    },
    {
      "id": "SG-007",
      "name": "DataColumnSidecar Construction from Payload",
      "description": "Defines the core mechanism for constructing DataColumnSidecars from blobs received via the execution engine (engine_getPayloadV5). For each blob, cells and proofs are extracted from the BlobsBundle, then passed to get_data_column_sidecars_from_block to assemble the full set of sidecars for distribution.",
      "invariants": [
        {
          "id": "INV-015",
          "text": "For each blob i, its cell proofs in blobs_bundle.proofs span the range [i * CELLS_PER_EXT_BLOB, (i + 1) * CELLS_PER_EXT_BLOB)."
        },
        {
          "id": "INV-016",
          "text": "cells_and_kzg_proofs is constructed by pairing compute_cells(blob) with the corresponding proofs from blobs_bundle.proofs for each blob."
        },
        {
          "id": "INV-017",
          "text": "The number of DataColumnSidecars produced equals NUMBER_OF_COLUMNS, one per column index."
        }
      ],
      "pre_conditions": [
        {
          "id": "PRE-005",
          "text": "blobs_bundle must be obtained from a call to engine_getPayloadV5."
        },
        {
          "id": "PRE-006",
          "text": "len(blobs_bundle.blobs) == len(blobs_bundle.commitments)."
        },
        {
          "id": "PRE-007",
          "text": "len(blobs_bundle.proofs) == CELLS_PER_EXT_BLOB * len(blobs_bundle.blobs)."
        }
      ],
      "post_conditions": [
        {
          "id": "POST-003",
          "text": "Produces a list of cells_and_kzg_proofs where each entry pairs a cell with its corresponding KZG proof from the bundle."
        }
      ],
      "functions": [],
      "data_structures": [],
      "state_variables": [],
      "code_snippets": [
        {
          "id": "CS-001",
          "language": "python",
          "description": "Construction of cells_and_kzg_proofs from blobs_bundle for sidecar assembly.",
          "code": "cells_and_kzg_proofs = []\nfor i, blob in enumerate(blobs_bundle.blobs):\n    start = i * CELLS_PER_EXT_BLOB\n    end = (i + 1) * CELLS_PER_EXT_BLOB\n    cell_proofs = zip(compute_cells(blob), blobs_bundle.proofs[start:end])\n    cells_and_kzg_proofs.extend(cell_proofs)"
        }
      ]
